import React, { useContext } from "react";
import { Context } from "../index";
import { useHistory } from "react-router-dom";
import { observer } from "mobx-react-lite";
import { Nav, Navbar, Container, Button, Dropdown } from 'react-bootstrap';
import { LOGIN_ROUTE, ADD_PRODUCT_ROUTE, ADMIN_ROUTE, FAVORITES_ROUTE, PROFILE_ROUTE, SHOP_ROUTE } from "../utils/const"; 
import logo from '../assets/logo.png'; 
import favorite from '../assets/Favorite.png'; 
import prof from '../assets/Profile.png'; 
import '../styles.css';

const NavBar = () => {
    const { user } = useContext(Context);
    const history = useHistory();

    const logOut = () => {
        user.setUser({});
        user.setIsAuth(false);
        localStorage.removeItem('token');
    };

    return (
        <Navbar collapseOnSelect expand="lg" className="navbar">
            <Container>
                <img 
                    src={logo} 
                    alt="Logo" 
                />
                {/* Название магазина как ссылка на главную */}
                <Navbar.Brand 
                    style={{ cursor: 'pointer' }} 
                    onClick={() => history.push(SHOP_ROUTE)}
                >
                    My Bag
                </Navbar.Brand>
                <Navbar.Toggle aria-controls="responsive-navbar-nav" />
                <Navbar.Collapse id="responsive-navbar-nav">
                    <Nav className="me-auto">
                        {/* Кнопки админ панели показываются только для ADMIN */}
                        {user.isAuth && user.user.role === 'ADMIN' && (
                            <>
                                <Button 
                                    variant="outline-dark" 
                                    onClick={() => history.push('/admin/add-type')}
                                    className="nav-button me-2"
                                >
                                    ➕ Добавить тип
                                </Button>
                                <Button 
                                    variant="outline-dark" 
                                    onClick={() => history.push('/admin/users')}
                                    className="nav-button me-2"
                                >
                                    👥 Пользователи
                                </Button>
                            </>
                        )}
                    </Nav>
                    {user.isAuth ? (
                        <Nav>
                            <Button 
                                variant="outline-dark" 
                                onClick={() => history.push(FAVORITES_ROUTE)}
                                className="nav-button"
                            >
                                <img 
                                    src={favorite} 
                                    alt="Favorites"
                                    className="navbarimg"
                                />
                                <span className="nav-text">Избранное</span>
                            </Button>
                            <Button 
                                variant="outline-dark" 
                                onClick={() => history.push(PROFILE_ROUTE)} 
                                className="nav-button"
                            >
                                <img 
                                    src={prof} 
                                    alt="Profile"
                                    className="navbarimg"
                                />
                                <span className="nav-text">Профиль</span>
                            </Button>
                            
                            <Button 
                                variant="outline-dark" 
                                onClick={() => history.push(ADD_PRODUCT_ROUTE)}
                                className="nav-button"
                            >
                                <span className="nav-text">Добавить товар</span>
                            </Button>
                            <Button 
                                variant="outline-dark" 
                                onClick={() => logOut()}
                                className="nav-button"
                            >
                                Выйти
                            </Button>
                        </Nav>
                    ) : (
                        <Nav>
                            <Button variant="outline-dark" onClick={() => history.push(LOGIN_ROUTE)}>
                                Авторизоваться
                            </Button>
                        </Nav>
                    )}
                </Navbar.Collapse>
            </Container>
        </Navbar>
    );
};

export default observer(NavBar);
